"use client";

import Link from "next/link";
import { useRouter } from "next/navigation";
import { FormEvent, useCallback, useEffect, useMemo, useState } from "react";

type Json = Record<string, any>;
type Mode = "home" | "login" | "onboarding" | "setup" | "invite" | "team" | "students" | "training" | "execution" | "evolution" | "agents" | "library" | "security" | "audit" | "settings" | "agenda" | "reports" | "finance";
type LoadState = "idle" | "loading" | "success" | "error";
type RouteCopy = { eyebrow: string; title: string; text: string };
// Legacy public-copy contract: Gerencie seus alunos, treinos e evolução

const routeCopy: Record<Mode, RouteCopy> = {
  home: { eyebrow: "Console", title: "Dashboard operacional por perfil.", text: "Cada papel entra direto no que precisa: dono acompanha a operação, professor revisa treinos e aluno executa com GIFs." },
  login: { eyebrow: "Acesso seguro", title: "Entre na sua operação FitCore.", text: "Use seu e-mail ou identificador e sua senha. A unidade só é necessária em contas legadas ou multioperação." },
  onboarding: { eyebrow: "Novo negócio", title: "Criar academia, estúdio, box ou personal.", text: "O cadastro cria a unidade, gestor proprietário e leva direto para o setup guiado." },
  setup: { eyebrow: "Configuração guiada", title: "Complete a primeira operação da unidade.", text: "Siga as etapas reais: equipe, aluno, treino, execução e evolução. O progresso fica salvo por unidade." },
  invite: { eyebrow: "Convite", title: "Aceitar convite da unidade.", text: "Confira o convite, defina seu identificador e crie senha ou código de acesso." },
  team: { eyebrow: "Equipe", title: "Usuários e papéis da unidade.", text: "Crie professores e alunos sem copiar IDs; o sistema vincula cada pessoa ao negócio atual." },
  students: { eyebrow: "Alunos", title: "Cadastro de aluno em fluxo guiado.", text: "Escolha professor responsável por lista, registre objetivo e avance para prescrição." },
  training: { eyebrow: "Treinos", title: "Prescrição com seleção real de aluno.", text: "Escolha o aluno no dropdown, monte o treino e libere para execução após revisão." },
  execution: { eyebrow: "Execução", title: "Treino do dia com demonstração em GIF.", text: "O aluno vê o que fazer, marca cada exercício, registra esforço e conclui sem sair da sessão." },
  evolution: { eyebrow: "Evolução", title: "Histórico e progresso no aluno correto.", text: "A evolução abre com métricas, gráfico e histórico filtrados pela sessão e pelo papel." },
  agents: { eyebrow: "Assistente IA", title: "Assistente para prescrição, acompanhamento e gestão.", text: "Agentes ajudam o profissional a criar treinos, revisar progresso, orientar alunos e registrar decisões com auditoria." },
  library: { eyebrow: "Biblioteca", title: "Exercícios com GIFs e explicações técnicas.", text: "Cada exercício mostra demonstração, músculos trabalhados, séries, descanso e cuidados de execução." },
  security: { eyebrow: "Segurança", title: "LGPD, sessão e permissões por papel.", text: "Dados protegidos, sessão ativa, auditoria e acesso filtrado por unidade." },
  audit: { eyebrow: "Auditoria", title: "Histórico de ações da operação.", text: "Registro de eventos por unidade, usuário, papel e recurso operacional." },
  settings: { eyebrow: "Configurações", title: "Ajustes da unidade e experiência.", text: "Preferências do painel, segurança, módulos e parâmetros da operação." },
  agenda: { eyebrow: "Agenda", title: "Agenda operacional da unidade.", text: "Organize aulas, avaliações, retornos e compromissos do time." },
  reports: { eyebrow: "Relatórios", title: "Indicadores e relatórios do negócio.", text: "Acompanhe alunos, execuções, frequência, evolução e alertas do time." },
  finance: { eyebrow: "Financeiro", title: "Visão financeira da operação fitness.", text: "Acompanhe planos, pendências, receitas previstas e indicadores de retenção." },
};

const exerciseMedia = [
  { slug: "0024-barbell-bench-front-squat", name: "Agachamento frontal", muscles: "Quadríceps · Glúteos · Core", sets: "4 × 10 repetições", rest: "60 segundos", cue: "Coluna neutra, joelhos alinhados e amplitude controlada." },
  { slug: "0026-barbell-bench-squat", name: "Agachamento livre", muscles: "Pernas · Glúteos", sets: "4 × 10 repetições", rest: "60 segundos", cue: "Desça com controle e suba mantendo o tronco firme." },
  { slug: "0150-cable-bar-lateral-pulldown", name: "Puxada alta", muscles: "Costas · Bíceps", sets: "4 × 12 repetições", rest: "60 segundos", cue: "Puxe com as costas, sem jogar o tronco para trás." },
  { slug: "0289-dumbbell-bench-press", name: "Supino com halteres", muscles: "Peitoral · Ombros · Tríceps", sets: "4 × 10 repetições", rest: "60 segundos", cue: "Controle a descida e mantenha escápulas estáveis." },
  { slug: "0159-cable-decline-seated-wide-grip-row", name: "Remada sentada", muscles: "Costas · Romboides · Bíceps", sets: "4 × 12 repetições", rest: "60 segundos", cue: "Traga os cotovelos para trás sem elevar ombros." },
  { slug: "0010-assisted-hanging-knee-raise-with-throw-down", name: "Elevação de joelhos", muscles: "Abdômen · Core", sets: "3 × 12 repetições", rest: "45 segundos", cue: "Evite balanço e contraia o abdômen no topo." },
];
const agentPrompts = ["Criar treino personalizado", "Ajustar volume e intensidade", "Revisar progresso de um aluno", "Gerar orientação para o aluno"];

async function api(path: string, options: RequestInit = {}): Promise<Json> {
  const res = await fetch(path, { cache: "no-store", credentials: "include", headers: { "content-type": "application/json", ...(options.headers || {}) }, ...options });
  const text = await res.text();
  const data = text ? JSON.parse(text) : {};
  if (!res.ok) throw new Error(data.mensagem || data.erro || data.reason || `HTTP ${res.status}`);
  return data;
}
function safe(value: any): string { return value === undefined || value === null || value === "" ? "—" : String(value); }
function numberText(value: any): string { const n = Number(value ?? 0); return Number.isFinite(n) ? n.toLocaleString("pt-BR", { maximumFractionDigits: 1 }) : "0"; }
function formPayload(form: HTMLFormElement): Json { const out: Json = {}; new FormData(form).forEach((raw, key) => { const value = typeof raw === "string" ? raw.trim() : String(raw); if (!value) return; out[key] = /^\d+$/.test(value) ? Number(value) : value; }); return out; }
function roleOf(session: Json | null): string { return String(session?.actor_role || "visitante").toLowerCase(); }
function isStaffRole(role: string): boolean { return role === "gestor" || role === "professor"; }
function statusText(error: string, fallback = "Nenhum registro carregado") { return error ? `Erro: ${error}` : fallback; }

export function FitCoreRouteClient({ mode }: { mode: Mode }) {
  const router = useRouter();
  const copy = routeCopy[mode];
  const [session, setSession] = useState<Json | null>(null);
  const [navigation, setNavigation] = useState<Json | null>(null);
  const [state, setState] = useState<LoadState>("idle");
  const [error, setError] = useState("");
  const [toast, setToast] = useState<Json | null>(null);
  const [team, setTeam] = useState<Json>({ users: [], invites: [] });
  const [students, setStudents] = useState<Json>({ students: [] });
  const [prescriptions, setPrescriptions] = useState<Json>({ prescriptions: [] });
  const [executions, setExecutions] = useState<Json>({ executions: [] });
  const [evolution, setEvolution] = useState<Json>({ students: [], weekly: [], summary: {} });
  const [setup, setSetup] = useState<Json>({ steps: [], progress_percent: 0 });
  const [detail, setDetail] = useState<Json | null>(null);
  const [agentAnswer, setAgentAnswer] = useState<Json | null>(null);
  const [dashboard, setDashboard] = useState<Json | null>(null);
  const [studentQuery, setStudentQuery] = useState("");
  const role = roleOf(session);
  const isStaff = isStaffRole(role);
  const prescriptionItems = prescriptions?.prescriptions || prescriptions?.workouts || [];
  const executionItems = executions?.executions || [];
  const firstStudentId = useMemo(() => studentQuery || students?.students?.[0]?.id || "", [studentQuery, students]);
  const firstPrescriptionId = useMemo(() => prescriptionItems?.[0]?.id || "", [prescriptionItems]);
  const firstExecutionId = useMemo(() => executionItems?.find((item: Json) => item.status === "em_execucao")?.id || executionItems?.[0]?.id || "", [executionItems]);

  useEffect(() => { const params = new URLSearchParams(window.location.search); setStudentQuery(params.get("student") || ""); }, [mode]);

  const loadSession = useCallback(async () => {
    try { const result = await api(`/api/mvp-15/session?v=${Date.now()}`); const current = result.current_session || null; setSession(current); if (current) setNavigation(await api(`/api/mvp-17/navigation?v=${Date.now()}`).catch(() => null)); else setNavigation(null); return current; }
    catch { setSession(null); setNavigation(null); return null; }
  }, []);

  const loadRouteData = useCallback(async (target: Mode = mode) => {
    setState("loading"); setError("");
    try {
      const current = await loadSession(); const currentRole = roleOf(current); const staff = isStaffRole(currentRole);
      const broad = ["setup", "home", "team", "students", "training", "execution", "evolution", "agents", "library", "security", "audit", "settings", "agenda", "reports", "finance"].includes(target);
      if (target === "home" && currentRole !== "visitante") {
        const consolidated = await api(`/api/mvp-37/dashboard?v=${Date.now()}`).catch(() => null);
        if (consolidated?.ok) {
          setDashboard(consolidated);
          if (consolidated.data?.setup) setSetup(consolidated.data.setup);
          if (consolidated.data?.team) setTeam(consolidated.data.team);
          if (consolidated.data?.students) setStudents(consolidated.data.students);
          if (consolidated.data?.prescriptions) setPrescriptions(consolidated.data.prescriptions);
          if (consolidated.data?.executions) setExecutions(consolidated.data.executions);
          if (consolidated.data?.evolution) setEvolution(consolidated.data.evolution);
          setState("success");
          return;
        }
      }
      if (currentRole === "gestor" && broad) setSetup(await api(`/api/mvp-31/setup?v=${Date.now()}`).catch(() => ({ steps: [], progress_percent: 0 })));
      if (currentRole === "gestor" && broad) setTeam(await api(`/api/mvp-22/users?v=${Date.now()}`).catch(() => ({ users: [], invites: [] })));
      if (staff && ["students", "training", "home", "agents", "library", "reports", "agenda", "execution", "evolution"].includes(target)) setStudents(await api(`/api/mvp-23/students?limit=100&v=${Date.now()}`));
      if (["training", "execution", "home", "agents", "library", "reports"].includes(target)) {
        if (staff) setPrescriptions(await api(`/api/mvp-24/prescriptions?limit=100&v=${Date.now()}`));
        if (currentRole === "aluno") setPrescriptions(await api(`/api/mvp-24/my-workouts?status=aprovado&limit=60&v=${Date.now()}`));
      }
      if (["execution", "home", "agents", "reports", "agenda"].includes(target)) {
        if (currentRole === "aluno") setExecutions(await api(`/api/mvp-25/my-executions?limit=80&v=${Date.now()}`));
        if (staff) setExecutions(await api(`/api/mvp-25/executions?limit=100&v=${Date.now()}`));
      }
      if (["evolution", "home", "agents", "reports"].includes(target)) {
        if (staff) setEvolution(await api(`/api/mvp-26/evolution?limit=100&v=${Date.now()}`));
        if (currentRole === "aluno") setEvolution(await api(`/api/mvp-26/my-evolution?limit=100&v=${Date.now()}`));
      }
      setState("success");
    } catch (err) { setError(err instanceof Error ? err.message : "Não foi possível carregar os dados."); setState("error"); }
  }, [loadSession, mode]);
  useEffect(() => { loadRouteData(mode); }, [loadRouteData, mode]);
  useEffect(() => { const cards = Array.from(document.querySelectorAll<HTMLElement>(".panel, .session-card, .module-card, .metric, .flow-card, .exercise-media-card, .agent-panel")); const update = (event: PointerEvent) => cards.forEach((card) => { const r = card.getBoundingClientRect(); if (event.clientX < r.left || event.clientX > r.right || event.clientY < r.top || event.clientY > r.bottom) return; card.style.setProperty("--card-x", `${event.clientX - r.left}px`); card.style.setProperty("--card-y", `${event.clientY - r.top}px`); }); window.addEventListener("pointermove", update, { passive: true }); return () => window.removeEventListener("pointermove", update); }, [mode]);

  async function runAction(label: string, action: () => Promise<Json>, refreshTarget: Mode = mode): Promise<Json | null> { setToast({ type: "loading", title: label, message: "Processando..." }); try { const result = await action(); setToast({ type: "success", title: label, message: "Concluído com sucesso.", result }); setDetail(result); await loadRouteData(refreshTarget); return result; } catch (err) { setToast({ type: "error", title: label, message: err instanceof Error ? err.message : "Ação não concluída." }); return null; } }
  async function submitLogin(event: FormEvent<HTMLFormElement>) { event.preventDefault(); const payload = formPayload(event.currentTarget); const result = await runAction("Entrar", () => api("/api/mvp-19/login", { method: "POST", body: JSON.stringify(payload) }), "home"); if (result?.session || result?.ok) router.push("/dashboard"); }
  async function logout() { const result = await runAction("Logout", () => api("/api/mvp-15/session/logout", { method: "POST", body: "{}" }), "login"); if (result) { setSession(null); router.push("/login"); } }
  async function submitOnboarding(event: FormEvent<HTMLFormElement>) { event.preventDefault(); const payload = formPayload(event.currentTarget); if (String(payload.secret || "") !== String(payload.confirm_secret || "")) { setToast({ type: "error", title: "Confira sua senha", message: "A confirmação da senha não confere." }); return; } const result = await runAction("Criar operação", () => api("/api/mvp-21/onboarding", { method: "POST", body: JSON.stringify(payload) }), "setup"); if (result?.ok) router.push("/setup"); }
  async function submitUser(event: FormEvent<HTMLFormElement>) { event.preventDefault(); const payload = formPayload(event.currentTarget); await runAction("Criar usuário", () => api("/api/mvp-22/users", { method: "POST", body: JSON.stringify(payload) }), "team"); }
  async function submitInvite(event: FormEvent<HTMLFormElement>) { event.preventDefault(); const payload = formPayload(event.currentTarget); await runAction("Gerar convite", () => api("/api/mvp-22/users/invite", { method: "POST", body: JSON.stringify(payload) }), "team"); }
  async function submitInviteAccept(event: FormEvent<HTMLFormElement>) { event.preventDefault(); const payload = formPayload(event.currentTarget); const result = await runAction("Aceitar convite", () => api("/api/mvp-22/invites/accept", { method: "POST", body: JSON.stringify(payload) }), "home"); if (result?.ok) router.push("/"); }
  async function submitStudent(event: FormEvent<HTMLFormElement>) { event.preventDefault(); const payload = formPayload(event.currentTarget); const result = await runAction("Cadastrar aluno", () => api("/api/mvp-23/students", { method: "POST", body: JSON.stringify(payload) }), "students"); const studentId = result?.student?.id || result?.created?.id; if (studentId) router.push(`/treinos?student=${encodeURIComponent(studentId)}`); }
  async function submitPrescription(event: FormEvent<HTMLFormElement>) { event.preventDefault(); const payload = formPayload(event.currentTarget); payload.exercicios = String(payload.exercicios || "").split("\n").map((item) => item.trim()).filter(Boolean); const result = await runAction("Criar prescrição", () => api("/api/mvp-24/prescriptions", { method: "POST", body: JSON.stringify(payload) }), "training"); if (result?.prescription?.id) setDetail(result); }
  async function reviewPrescription(id: string, status: "aprovado" | "ajustes_solicitados") { await runAction(status === "aprovado" ? "Aprovar treino" : "Solicitar ajustes", () => api(`/api/mvp-24/prescriptions/${encodeURIComponent(id)}/review`, { method: "POST", body: JSON.stringify({ status, observacoes: status === "aprovado" ? "Treino aprovado no painel." : "Ajustes solicitados no painel." }) }), "training"); }
  async function startExecution(workoutId: string) { await runAction("Iniciar treino", () => api("/api/mvp-25/executions/start", { method: "POST", body: JSON.stringify({ workout_id: workoutId }) }), "execution"); }
  async function markExerciseDone(executionId: string, index: number) { await runAction("Marcar exercício", () => api(`/api/mvp-25/executions/${encodeURIComponent(executionId)}/exercises/${index}/done`, { method: "POST", body: JSON.stringify({ observacao: "Marcado no painel." }) }), "execution"); }
  async function finishExecution(event: FormEvent<HTMLFormElement>) { event.preventDefault(); const payload = formPayload(event.currentTarget); const id = String(payload.execution_id || ""); delete payload.execution_id; await runAction("Concluir treino", () => api(`/api/mvp-25/executions/${encodeURIComponent(id)}/finish`, { method: "POST", body: JSON.stringify(payload) }), "execution"); }
  async function loadStudentEvolution(studentId: string) { await runAction("Carregar evolução", () => api(`/api/mvp-26/students/${encodeURIComponent(studentId)}/evolution?limit=100`), "evolution"); }
  async function askAgent(prompt: string) { const result = await runAction("Assistente IA", () => api("/api/mvp-32/agent", { method: "POST", body: JSON.stringify({ prompt }) }), mode); if (result) setAgentAnswer(result); }

  const publicHome = mode === "home" && !session;
  const focusedEntry = mode === "login" || mode === "onboarding" || mode === "invite";
  return <section className={`route-page premium-workspace ${focusedEntry ? "entry-route" : ""}`} data-mode={mode}>{focusedEntry ? null : <TopSearch session={session} />}{focusedEntry ? null : <div className={`route-hero ${publicHome ? "public-hero" : ""}`}><div><p className="eyebrow">{copy.eyebrow}</p><h1>{copy.title}</h1><p>{copy.text}</p><div className="hero-actions-inline"><Link className="primary-pill" href="/cadastro">Começar agora</Link><Link className="button secondary" href="/login">Entrar</Link></div></div>{publicHome ? <LandingPreviewCard /> : <SessionPanel session={session} state={state} error={error} onRefresh={() => loadRouteData(mode)} />}</div>}{!publicHome && !focusedEntry ? <RoleDashboard session={session} navigation={navigation} team={team} students={students} prescriptions={prescriptions} executions={executions} evolution={evolution} setup={setup} /> : null}<Toast toast={toast} onClose={() => setToast(null)} />
    {mode === "home" && <HomePanel session={session} role={role} setup={setup} team={team} students={students} prescriptions={prescriptions} executions={executions} evolution={evolution} agentAnswer={agentAnswer} onAskAgent={askAgent} dashboard={dashboard} />}
    {mode === "login" && <LoginPanel onSubmit={submitLogin} onLogout={logout} state={state} />}
    {mode === "onboarding" && <OnboardingPanel onSubmit={submitOnboarding} state={state} />}
    {mode === "setup" && <SetupPanel setup={setup} session={session} state={state} error={error} onRefresh={() => loadRouteData("setup")} />}
    {mode === "invite" && <InvitePanel onSubmit={submitInviteAccept} state={state} />}
    {mode === "team" && <TeamPanel role={role} data={team} detail={detail} state={state} error={error} onCreate={submitUser} onInvite={submitInvite} onRefresh={() => loadRouteData("team")} />}
    {mode === "students" && <StudentsPanel role={role} team={team} data={students} detail={detail} state={state} error={error} onSubmit={submitStudent} onRefresh={() => loadRouteData("students")} />}
    {mode === "training" && <TrainingPanel role={role} students={students?.students || []} data={prescriptions} detail={detail} state={state} error={error} selectedStudentId={firstStudentId} onSubmit={submitPrescription} onReview={reviewPrescription} onRefresh={() => loadRouteData("training")} />}
    {mode === "execution" && <ExecutionPanel role={role} workouts={prescriptions} executions={executions} detail={detail} state={state} error={error} firstPrescriptionId={firstPrescriptionId} firstExecutionId={firstExecutionId} onStart={startExecution} onMarkDone={markExerciseDone} onFinish={finishExecution} onRefresh={() => loadRouteData("execution")} onAskAgent={askAgent} agentAnswer={agentAnswer} />}
    {mode === "evolution" && <EvolutionPanel data={evolution} detail={detail} state={state} error={error} isStaff={isStaff} onStudent={loadStudentEvolution} onRefresh={() => loadRouteData("evolution")} />}
    {mode === "agents" && <AgentsPanel role={role} data={{ team, students, prescriptions, executions, evolution }} answer={agentAnswer} onAsk={askAgent} />}
    {mode === "library" && <LibraryPanel workouts={prescriptions} onAskAgent={askAgent} />}
    {mode === "security" && <SecurityPanel session={session} />}
    {mode === "audit" && <AuditPanel session={session} executions={executions} />}
    {mode === "settings" && <SettingsPanel session={session} />}
    {mode === "agenda" && <AgendaPanel students={students} executions={executions} />}
    {mode === "reports" && <ReportsPanel students={students} prescriptions={prescriptions} executions={executions} evolution={evolution} />}
    {mode === "finance" && <FinancePanel students={students} />}
  </section>;
}


function RoleConsole37({ dashboard, agentAnswer, onAskAgent }: { dashboard: Json; agentAnswer: Json | null; onAskAgent: (prompt: string) => void }) {
  const role = String(dashboard.actor_role || "aluno");
  const data = dashboard.data || {};
  const kpis = dashboard.kpis || [];
  const actions = dashboard.actions || [];
  const profile = dashboard.profile || {};
  const students = data.students?.students || [];
  const prescriptions = data.prescriptions?.prescriptions || [];
  const executions = data.executions?.executions || [];
  const evolutionStudents = data.evolution?.students || [];
  const workout = dashboard.workout_today;
  const title = profile.title || "Dashboard real";
  return <div className={`role-console37 role-${role}`}>
    <section className="panel console37-hero wide">
      <div><span className="eyebrow">Console inteligente</span><h2>{safe(title)}</h2><p>{safe(profile.summary || "Dados consolidados da unidade e do papel logado.")}</p><div className="role-next-actions">{actions.map((item: Json) => <Link className="primary-pill" key={item.href} href={item.href}>{safe(item.label)}</Link>)}</div></div>
      <aside className="console37-source"><small>Fonte de confiança</small><strong>Dados da unidade</strong><span>Métricas, permissões e treino real</span><em>{safe(dashboard.tenant_slug)} · {safe(dashboard.actor_role)}</em></aside>
    </section>
    <section className="console-kpi-grid">{kpis.map((item: Json) => <Metric key={item.label} label={safe(item.label)} value={safe(item.value)} hint={safe(item.hint)} />)}</section>
    <div className="console-main-grid">
      <section className="panel console-primary-panel"><PanelTitle title={role === "aluno" ? "Treino aprovado automaticamente" : role === "professor" ? "Fila real de alunos e treinos" : "Operação real do tenant"} action="Atualizar" /><DashboardMainList37 role={role} students={students} prescriptions={prescriptions} executions={executions} evolutionStudents={evolutionStudents} /></section>
      <aside className="console-side-stack"><WorkoutToday37 workout={workout} /><AgentContext37 role={role} dashboard={dashboard} answer={agentAnswer} onAsk={onAskAgent} /><SecurityMini37 /></aside>
    </div>
  </div>;
}

function DashboardMainList37({ role, students, prescriptions, executions, evolutionStudents }: { role: string; students: Json[]; prescriptions: Json[]; executions: Json[]; evolutionStudents: Json[] }) {
  if (role === "aluno") return <div className="rich-list37">{prescriptions.length ? prescriptions.slice(0, 4).map((item) => <article key={item.id}><b>{safe(item.nome_treino || item.objetivo)}</b><span>{safe(item.status)} · {safe(item.student_name)}</span><small>{safe(item.orientacoes || "Treino liberado para execução com GIFs e registro de esforço.")}</small></article>) : <EmptyState37 title="Nenhum treino liberado" text="Quando o professor aprovar um treino, ele aparece aqui automaticamente." />}</div>;
  if (role === "professor") return <div className="rich-list37">{[...prescriptions.slice(0, 3), ...students.slice(0, 3)].map((item: Json, index: number) => <article key={item.id || index}><b>{safe(item.nome_treino || item.nome_publico || item.student_name || item.name)}</b><span>{safe(item.status || item.objetivo || "aluno ativo")}</span><small>{safe(item.professor_name || item.nivel || "Acompanhamento disponível por tenant.")}</small></article>)}{!prescriptions.length && !students.length ? <EmptyState37 title="Sem fila crítica" text="Crie alunos ou prescrições para alimentar o painel do professor." /> : null}</div>;
  return <div className="rich-list37">{[...evolutionStudents.slice(0, 4), ...executions.slice(0, 2)].map((item: Json, index: number) => <article key={item.student_id || item.id || index}><b>{safe(item.student_name || item.nome_treino || item.objetivo)}</b><span>{item.progress_percent !== undefined ? `${item.progress_percent}% de progresso` : safe(item.status || "operação")}</span><small>{item.average_effort ? `Esforço médio ${item.average_effort}` : safe(item.professor_name || "dados reais do tenant")}</small></article>)}{!evolutionStudents.length && !executions.length ? <EmptyState37 title="Dados operacionais em formação" text="Execute o primeiro treino para preencher evolução, frequência e histórico." /> : null}</div>;
}

function EmptyState37({ title, text }: { title: string; text: string }) { return <article className="empty-state37"><b>{title}</b><span>{text}</span></article>; }

function WorkoutToday37({ workout }: { workout: Json | null }) {
  if (!workout) return <section className="panel"><h2>Treino do dia</h2><EmptyState37 title="Aguardando treino aprovado" text="O treino aparece aqui quando estiver liberado para o aluno logado." /></section>;
  const exercises = workout.exercises || [];
  return <section className="panel workout37"><h2>{safe(workout.title)}</h2><p>{safe(workout.status)} · {safe(workout.student_name || "aluno logado")}</p><div>{exercises.slice(0, 3).map((item: Json) => <article key={item.ordem}><img src={item.gif_url} alt={`Demonstração de ${safe(item.nome || item.name)}`} /><span>{item.ordem}</span><strong>{safe(item.nome || item.name || "Exercício")}</strong></article>)}</div><Link className="button secondary full" href="/execucao">Abrir execução</Link></section>;
}

function AgentContext37({ role, dashboard, answer, onAsk }: { role: string; dashboard: Json; answer: Json | null; onAsk: (prompt: string) => void }) {
  const facts = dashboard.agent_context?.facts || [];
  const prompt = role === "aluno" ? "Explique meu treino do dia e cuidados de execução" : role === "professor" ? "Analise meus alunos e treinos pendentes" : "Resuma a operação do tenant e prioridades de hoje";
  return <section className="panel agent-context37"><h2>IA contextual</h2><p>Contexto enviado pela API consolidada, filtrado por tenant e papel.</p><div>{facts.slice(0, 4).map((fact: string) => <span key={fact}>{fact}</span>)}</div><button type="button" onClick={() => onAsk(prompt)}>Usar IA com este contexto</button>{answer?.reply ? <article className="agent-answer"><strong>Resposta</strong><p>{safe(answer.reply)}</p></article> : null}</section>;
}

function SecurityMini37() { return <section className="panel security-mini37"><h2>Segurança ativa</h2><span>Sessão assinada</span><span>Tenant isolado</span><span>RBAC por papel</span><span>LGPD e auditoria</span></section>; }

function TopSearch({ session }: { session: Json | null }) { return <div className="workspace-top"><div className="global-search"><span>⌕</span><input aria-label="Busca" placeholder="Buscar alunos, treinos ou exercícios..." /></div><div className="top-tenant"><strong>{session?.tenant_slug || "FitCore Pro"}</strong><span>{session ? safe(session.actor_role) : "Acesso público"}</span></div></div>; }
function LandingPreviewCard() { return <aside className="landing-preview-card" aria-label="Prévia do FitCore Pro"><div className="preview-top"><span>Plataforma ativa</span><strong>FitCore Pro</strong></div><div className="preview-metrics"><Metric label="Alunos" value="124" /><Metric label="Execuções" value="892" /><Metric label="Evolução" value="+28%" /></div><div className="preview-chart"><i style={{height:"38%"}} /><i style={{height:"52%"}} /><i style={{height:"61%"}} /><i style={{height:"78%"}} /><i style={{height:"88%"}} /></div><p>Gestão completa para dono, professor e aluno: treinos, GIFs, IA, evolução, segurança e auditoria.</p></aside>; }
function SessionPanel({ session, state, error, onRefresh }: { session: Json | null; state: LoadState; error: string; onRefresh: () => void }) { const logged = Boolean(session); return <aside className={`session-card ${logged ? "is-online" : "is-offline"}`}><small>{state === "loading" ? "Carregando" : logged ? "Sessão ativa" : "Entrada"}</small><strong>{logged ? safe(session?.actor_name) : "Entre para continuar"}</strong><span>{logged ? `${safe(session?.actor_role)} · ${safe(session?.tenant_slug)}` : statusText(error, "Entre ou crie uma unidade.")}</span><button type="button" className="secondary mini" onClick={onRefresh}>Atualizar</button></aside>; }
function Toast({ toast, onClose }: { toast: Json | null; onClose: () => void }) { if (!toast) return null; return <div className={`toast toast-${toast.type || "info"}`}><div><strong>{safe(toast.title)}</strong><span>{safe(toast.message)}</span></div><button type="button" className="secondary mini" onClick={onClose}>Fechar</button></div>; }
function RoleDashboard({ session, navigation, team, students, prescriptions, executions, evolution, setup }: { session: Json | null; navigation: Json | null; team: Json; students: Json; prescriptions: Json; executions: Json; evolution: Json; setup: Json }) { const role = roleOf(session); const kpis = role === "gestor" ? [["Configurar", `${setup?.progress_percent || 0}%`], ["Alunos", students?.total || students?.students?.length || 0], ["Treinos", prescriptions?.total || 0], ["Execuções", executions?.total || 0], ["LGPD", "OK"]] : role === "professor" ? [["Alunos", students?.total || students?.students?.length || 0], ["Treinos", prescriptions?.total || 0], ["Pendentes", prescriptions?.em_revisao || 0], ["Evolução", evolution?.students?.length || 0]] : role === "aluno" ? [["Treinos", prescriptions?.total || prescriptions?.prescriptions?.length || 0], ["Execuções", executions?.total || 0], ["Concluídos", executions?.concluidos || 0], ["Frequência", evolution?.student?.weekly_frequency || 0]] : [["Comece", 1], ["Entrar", 1], ["Unidade", 0], ["Fluxo", 6]]; const hrefs = role === "gestor" ? [["/setup", "Configurar"], ["/agents", "Assistente IA"], ["/equipe", "Equipe"], ["/alunos", "Alunos"], ["/relatorios", "Relatórios"]] : role === "professor" ? [["/agents", "IA do Professor"], ["/alunos", "Alunos"], ["/treinos", "Treinos pendentes"], ["/evolucao", "Progresso"]] : role === "aluno" ? [["/execucao", "Treino do dia"], ["/biblioteca", "Ver execução"], ["/evolucao", "Minha evolução"]] : [["/cadastro", "Criar negócio"], ["/login", "Entrar"]]; const title = role === "gestor" ? "Dashboard executivo" : role === "professor" ? "Painel do professor" : role === "aluno" ? "Painel do aluno" : "Visitante"; const note = role === "visitante" ? "Crie uma unidade ou entre para carregar o painel." : `${navigation?.menu?.length || hrefs.length} áreas disponíveis para esta sessão.`; return <section className={`role-dashboard role-dashboard-${role}`}><div className="role-copy"><span>Painel por papel</span><strong>{title}</strong><p>{note}</p></div><div className="role-metrics">{kpis.map(([label, value]) => <Metric label={String(label)} value={value} key={String(label)} />)}</div><div className="role-actions">{hrefs.map(([href, label]) => <Link key={href} className="primary-pill" href={href}>{label}</Link>)}</div></section>; }
function HomePanel({ session, role, setup, team, students, prescriptions, executions, evolution, agentAnswer, onAskAgent, dashboard }: { session: Json | null; role: string; setup: Json; team: Json; students: Json; prescriptions: Json; executions: Json; evolution: Json; agentAnswer: Json | null; onAskAgent: (prompt: string) => void; dashboard?: Json | null }) {
  if (dashboard?.ok) return <RoleConsole37 dashboard={dashboard} agentAnswer={agentAnswer} onAskAgent={onAskAgent} />;
  const studentList = students?.students || [];
  const prescriptionList = prescriptions?.prescriptions || prescriptions?.workouts || [];
  const executionList = executions?.executions || [];
  const setupSteps = setup?.steps || [];
  const config = role === "gestor" ? {
    label: "Dono / Gestor", title: "Operação completa da unidade", text: "Veja setup, equipe, alunos, treinos, execuções, evolução, segurança e agentes em um console único.", cta: "/setup", ctaText: "Continuar setup",
    metrics: [["Configurar", `${setup?.progress_percent || 0}%`], ["Equipe", team?.users?.length || 0], ["Alunos", students?.total || studentList.length || 0], ["Treinos", prescriptions?.total || prescriptionList.length || 0], ["Execuções", executions?.total || executionList.length || 0], ["LGPD", "Ativa"]],
    next: [["Criar professor", "/equipe"], ["Cadastrar aluno", "/alunos"], ["Prescrever treino", "/treinos"], ["Ver evolução", "/evolucao"]]
  } : role === "professor" ? {
    label: "Professor", title: "Treinos, alunos e evolução sob controle", text: "Acompanhe alunos, revise prescrições, use IA para ajustes e veja progresso sem acessar área administrativa indevida.", cta: "/treinos", ctaText: "Revisar treinos",
    metrics: [["Alunos", students?.total || studentList.length || 0], ["Treinos", prescriptions?.total || prescriptionList.length || 0], ["Pendentes", prescriptions?.em_revisao || prescriptionList.filter((item: Json) => item.status === "em_revisao").length || 0], ["Execuções", executions?.total || executionList.length || 0], ["Evolução", evolution?.students?.length || 0], ["IA", "Ativa"]],
    next: [["Abrir IA", "/agents"], ["Ver alunos", "/alunos"], ["Prescrever", "/treinos"], ["Progresso", "/evolucao"]]
  } : role === "aluno" ? {
    label: "Aluno", title: "Treino do dia com execução guiada", text: "Veja exercícios com GIF, inicie a sessão, marque o que concluiu e acompanhe sua evolução sem sair do sistema.", cta: "/execucao", ctaText: "Começar treino",
    metrics: [["Treinos", prescriptions?.total || prescriptionList.length || 0], ["Em execução", executionList.filter((item: Json) => item.status === "em_execucao").length || 0], ["Concluídos", executions?.concluidos || 0], ["Esforço", evolution?.student?.average_effort || "—"], ["Frequência", evolution?.student?.weekly_frequency || 0], ["LGPD", "OK"]],
    next: [["Treino do dia", "/execucao"], ["Biblioteca", "/biblioteca"], ["Minha evolução", "/evolucao"], ["Segurança", "/seguranca"]]
  } : {
    label: "Visitante", title: "Entre para carregar seu console", text: "A landing pública fica separada. O console real abre após login ou criação da unidade.", cta: "/login", ctaText: "Entrar",
    metrics: [["Unidade", "—"], ["Sessão", "—"], ["Papel", "—"], ["Dados", "Protegidos"], ["IA", "Prévia"], ["GIFs", "Ativos"]],
    next: [["Criar negócio", "/cadastro"], ["Entrar", "/login"], ["Ver segurança", "/seguranca"], ["Biblioteca", "/biblioteca"]]
  };
  const visibleStudents = studentList.slice(0, 5);
  const visiblePrescriptions = prescriptionList.slice(0, 5);
  return <div className={`role-console role-console-${role}`}>
    <section className="panel console-hero wide">
      <div><span className="eyebrow">{config.label}</span><h2>{config.title}</h2><p>{config.text}</p><div className="role-next-actions">{config.next.map(([label, href]) => <Link key={href} className="primary-pill" href={href}>{label}</Link>)}</div></div>
      <div className="console-hero-card"><span>Sessão</span><strong>{session?.actor_name || config.label}</strong><small>{session?.tenant_slug || "acesse para vincular ao tenant"}</small><Link className="button secondary" href={config.cta}>{config.ctaText}</Link></div>
    </section>
    <section className="panel wide"><div className="console-kpi-grid">{config.metrics.map(([label, value]) => <Metric key={String(label)} label={String(label)} value={value} />)}</div></section>
    <div className="console-main-grid">
      <section className="panel console-primary-panel"><PanelTitle title={role === "aluno" ? "Treino do dia" : role === "professor" ? "Fila do professor" : "Central da operação"} action={role === "aluno" ? "Executar" : "Abrir treinos"} onClick={() => { location.href = role === "aluno" ? "/execucao" : "/treinos"; }} />{role === "aluno" ? <ExerciseMediaGrid limit={4} /> : <div className="item-list">{visiblePrescriptions.length ? visiblePrescriptions.map((item: Json) => <article className="item rich-item" key={item.id}><strong>{safe(item.nome_treino || item.workout_name || item.id)}</strong><span>{safe(item.student_name || item.aluno_nome || "aluno")} · {safe(item.status)}</span><small>Use IA para ajustar volume, revisar execução e liberar o próximo treino.</small></article>) : <article className="item"><strong>Nenhum treino real cadastrado</strong><span>Cadastre um aluno e crie uma prescrição para preencher esta fila.</span></article>}</div>}</section>
      <aside className="console-side-stack"><AgentPanel role={role} answer={agentAnswer} onAsk={onAskAgent} /><section className="panel"><h2>Próximas ações</h2><div className="side-action-list">{config.next.map(([label, href]) => <Link key={href} href={href}><strong>{label}</strong><span>Abrir módulo</span></Link>)}</div></section><SecurityPanel session={session} compact /></aside>
    </div>
    <div className="console-main-grid bottom">
      <section className="panel"><h2>{role === "gestor" ? "Equipe e alunos" : role === "professor" ? "Alunos acompanhados" : "Minha orientação"}</h2><List empty="Fluxo guiado pronto para criar dados reais." items={visibleStudents} pick={(student) => [student.nome_publico || student.nome, student.objetivo || student.professor_nome || "acompanhamento", `${student.frequencia_semana || "—"}`]} /></section>
      <section className="panel"><h2>Biblioteca com GIFs</h2><ExerciseMediaGrid limit={3} compact /><Link className="button secondary full" href="/biblioteca">Abrir biblioteca completa</Link></section>
      <section className="panel"><h2>Evolução</h2><div className="metric-grid compact-metrics"><Metric label="Esforço" value={evolution?.summary?.average_effort || evolution?.student?.average_effort || 0} /><Metric label="Frequência" value={evolution?.summary?.weekly_frequency || evolution?.student?.weekly_frequency || 0} /></div><Chart weekly={evolution?.weekly || []} history={evolution?.history || []} /></section>
    </div>
    {role === "gestor" ? <section className="panel wide setup-mini"><PanelTitle title="Configuração da unidade" action="Abrir setup" onClick={() => { location.href = "/setup"; }} /><div className="setup-steps">{setupSteps.length ? setupSteps.map((step: Json) => <Link className={`setup-step ${step.done ? "is-done" : "is-open"}`} href={step.href || "/setup"} key={step.id}><span>{String(step.order || 1).padStart(2, "0")}</span><div><strong>{safe(step.title)}</strong><small>{step.done ? "Concluído" : "Pendente"}</small></div><em>{step.done ? "OK" : "Fazer"}</em></Link>) : config.next.map(([label, href], index) => <Link className="setup-step is-open" href={href} key={href}><span>{String(index + 1).padStart(2, "0")}</span><div><strong>{label}</strong><small>Etapa guiada</small></div><em>Abrir</em></Link>)}</div></section> : null}
  </div>;
}

function LoginPanel({ onSubmit, onLogout, state }: { onSubmit: (event: FormEvent<HTMLFormElement>) => void; onLogout: () => void; state: LoadState }) { return <div className="split-grid"><form className="panel operational-form" onSubmit={onSubmit}><FormHeader label="Acesso" title="Entrar com credencial" text="Use seu e-mail ou identificador. A unidade é opcional quando você usa a unidade padrão." /><label>E-mail ou identificador<input name="login_identifier" required type="text" inputMode="email" placeholder="seu@email.com" autoComplete="username" /></label><label>Senha ou código<input name="secret" required type="password" autoComplete="current-password" /></label><label>Unidade (opcional)<input name="tenant_slug" placeholder="ex: demo" autoComplete="off" /></label><div className="form-actions"><button type="submit" disabled={state === "loading"}>Entrar</button><button type="button" className="secondary" onClick={onLogout}>Sair da sessão</button></div></form><article className="panel guidance-panel"><h2>Entrada por perfil</h2><p>Depois do login, a navegação muda automaticamente para dono/gestor, professor ou aluno.</p><div className="mini-grid"><Metric label="Gestor" value="Operação" /><Metric label="Professor" value="Treinos" /><Metric label="Aluno" value="Execução" /><Metric label="Acesso" value="Filtrado" /></div></article></div>; }
function OnboardingPanel({ onSubmit, state }: { onSubmit: (event: FormEvent<HTMLFormElement>) => void; state: LoadState }) {
  return <div className="premium-signup-grid">
    <form className="panel operational-form premium-signup-form" onSubmit={onSubmit}>
      <FormHeader label="Comece com estrutura profissional" title="Crie sua operação FitCore" text="Seu acesso nasce com e-mail real, sessão assinada e dados persistidos no PostgreSQL." />
      <fieldset className="signup-section"><legend>Responsável</legend>
        <label>Nome completo<input name="owner_name" required minLength={3} autoComplete="name" placeholder="Seu nome e sobrenome" /></label>
        <label>E-mail profissional<input name="owner_email" required type="email" inputMode="email" autoComplete="email" placeholder="voce@empresa.com" /></label>
        <label className="field-span-2">WhatsApp / telefone<input name="owner_phone" required type="tel" inputMode="tel" autoComplete="tel" placeholder="(22) 99999-9999" /></label>
      </fieldset>
      <fieldset className="signup-section"><legend>Negócio</legend>
        <label>Nome do negócio<input name="business_name" required minLength={3} autoComplete="organization" placeholder="Ex: Fit Center Saquarema" /></label>
        <label>Tipo<select name="business_type" defaultValue="academia"><option value="academia">Academia</option><option value="estudio">Estúdio</option><option value="box">Box / Cross training</option><option value="personal">Personal trainer</option></select></label>
        <label>Endereço digital<input name="slug" placeholder="fit-center-saquarema" autoComplete="off" /></label>
        <label>Cidade<input name="city" autoComplete="address-level2" placeholder="Saquarema" /></label>
        <label>UF<input name="state" maxLength={2} autoComplete="address-level1" placeholder="RJ" /></label>
      </fieldset>
      <fieldset className="signup-section"><legend>Segurança</legend>
        <label>Crie sua senha<input name="secret" required type="password" minLength={10} autoComplete="new-password" placeholder="10+ caracteres, letras e número" /></label>
        <label>Confirme a senha<input name="confirm_secret" required type="password" minLength={10} autoComplete="new-password" placeholder="Repita sua senha" /></label>
      </fieldset>
      <div className="signup-consents">
        <label><input name="accept_terms" type="checkbox" required /> <span>Li e aceito os <Link href="/legal/terms" target="_blank">Termos de Uso</Link>.</span></label>
        <label><input name="accept_privacy" type="checkbox" required /> <span>Li e aceito a <Link href="/legal/privacy" target="_blank">Política de Privacidade</Link>.</span></label>
      </div>
      <button className="premium-submit" type="submit" disabled={state === "loading"}>{state === "loading" ? "Criando sua operação..." : "Criar minha operação →"}</button>
      <p className="signup-login-link">Já possui acesso? <Link href="/login">Entrar no FitCore</Link></p>
    </form>
    <aside className="panel premium-signup-aside">
      <span className="label">FitCore Pro</span><h2>Seu sistema pronto para operar de verdade.</h2>
      <p>Uma única conta conecta gestão, professores, alunos, prescrição, execução e evolução na Web.</p>
      <div className="signup-trust-grid"><article><strong>PostgreSQL</strong><span>Persistência real</span></article><article><strong>Sessão assinada</strong><span>Autenticação protegida</span></article><article><strong>3 perfis</strong><span>Gestor · Professor · Aluno</span></article><article><strong>Web responsiva</strong><span>Desktop e celular no mesmo sistema</span></article></div>
      <Process steps={["Criar conta", "Configurar equipe", "Cadastrar alunos", "Prescrever treinos", "Executar no Web", "Acompanhar evolução"]} />
      <p className="signup-privacy-note">Dados mínimos, isolamento por unidade e trilha de auditoria. Nada de dados fictícios para preencher painel.</p>
    </aside>
  </div>;
}
function InvitePanel({ onSubmit, state }: { onSubmit: (event: FormEvent<HTMLFormElement>) => void; state: LoadState }) { const [params, setParams] = useState({ tenant_slug: "", token: "", login_identifier: "" }); useEffect(() => { const q = new URLSearchParams(window.location.search); setParams({ tenant_slug: q.get("tenant_slug") || "", token: q.get("token") || "", login_identifier: q.get("login_identifier") || "" }); }, []); return <div className="split-grid"><form className="panel operational-form" onSubmit={onSubmit}><FormHeader label="Convite" title="Definir acesso" text="Use o link recebido e crie sua credencial para entrar no painel." /><label>Slug da unidade<input name="tenant_slug" required defaultValue={params.tenant_slug} placeholder="unidade" /></label><label>Token do convite<input name="token" required defaultValue={params.token} placeholder="token recebido" /></label><label>Nome<input name="nome" required placeholder="seu nome" /></label><label>Identificador<input name="login_identifier" required defaultValue={params.login_identifier} placeholder="seu.login" /></label><label>Senha ou código<input name="secret" required type="password" placeholder="mínimo 8 caracteres" /></label><button disabled={state === "loading"}>Aceitar convite e entrar</button></form><article className="panel guidance-panel"><h2>Acesso por convite</h2><p>Após aceitar, a sessão entra na unidade correta e o menu muda conforme o papel recebido.</p><div className="mini-grid"><Metric label="Papel" value="Automático" /><Metric label="Unidade" value="Vinculada" /><Metric label="Sessão" value="Assinada" /><Metric label="Acesso" value="Filtrado" /></div></article></div>; }
function SetupPanel({ setup, session, state, error, onRefresh }: { setup: Json; session: Json | null; state: LoadState; error: string; onRefresh: () => void }) { const steps = setup.steps || []; if (!session) return <PermissionPanel title="Configurar" text="Entre como gestor para continuar a configuração da unidade." />; return <div className="dashboard-grid setup-workspace"><section className="panel wide setup-board"><div className="setup-board-head"><div><span className="label">Checklist da unidade</span><h2>{setup.all_done ? "Operação pronta para testar" : "Continue a primeira operação"}</h2><p>{setup.all_done ? "Equipe, aluno, treino, execução e evolução já foram validados nesta unidade." : "Cada etapa usa dados reais do sistema e salva progresso no negócio atual."}</p></div><div className="setup-progress"><strong>{numberText(setup.progress_percent)}%</strong><span>concluído</span></div></div><div className="setup-meter"><i style={{ width: `${Math.max(0, Math.min(100, Number(setup.progress_percent || 0)))}%` }} /></div><div className="setup-steps">{steps.length ? steps.map((step: Json) => <Link className={`setup-step ${step.done ? "is-done" : "is-open"}`} href={step.href || "/"} key={step.id}><span>{String(step.order || 1).padStart(2, "0")}</span><div><strong>{safe(step.title)}</strong><small>{step.done ? "Concluído" : "Abrir etapa"} · {safe(step.count)} registro(s)</small></div><em>{step.done ? "OK" : "Fazer"}</em></Link>) : <article className="item"><strong>Configuração não carregada</strong><span>{statusText(error, state === "loading" ? "Carregando..." : "Atualize para calcular o progresso.")}</span></article>}</div><div className="row-actions"><button type="button" className="secondary" onClick={onRefresh}>Atualizar progresso</button><Link className="primary-pill" href={setup?.steps?.find?.((step: Json) => !step.done)?.href || "/evolucao"}>{setup.all_done ? "Ver evolução" : "Continuar etapa"}</Link></div></section><section className="panel setup-summary"><h2>Próxima ação</h2><p>{setup.all_done ? "Use os logins de teste para validar cada papel." : `Etapa atual: ${safe(setup.current_step)}`}</p><div className="mini-grid"><Metric label="Professor" value={setup?.counters?.professors_with_access || 0} /><Metric label="Alunos" value={setup?.counters?.students || 0} /><Metric label="Treinos" value={setup?.counters?.workouts || 0} /><Metric label="Execuções" value={setup?.counters?.completed_executions || 0} /></div></section></div>; }
function TeamPanel({ role, data, detail, state, error, onCreate, onInvite, onRefresh }: { role: string; data: Json; detail: Json | null; state: LoadState; error: string; onCreate: (event: FormEvent<HTMLFormElement>) => void; onInvite: (event: FormEvent<HTMLFormElement>) => void; onRefresh: () => void }) { const users = data.users || []; const invites = data.invites || []; if (role !== "gestor") return <PermissionPanel title="Equipe" text="Somente gestor administra usuários da unidade." />; return <div className="dashboard-grid"><section className="panel wide flow-guide"><FlowHeader current="Equipe" next="Alunos" href="/alunos" /><div className="flow-cards"><FlowCard title="1. Professor" text="Crie o professor que vai revisar treinos." /><FlowCard title="2. Aluno" text="Crie usuário aluno ou envie convite." /><FlowCard title="3. Cadastro operacional" text="No próximo passo, cadastre o aluno no módulo Alunos." /></div></section><form className="panel operational-form" onSubmit={onCreate}><FormHeader label="Equipe" title="Criar usuário" text="Usuário já entra vinculado à unidade atual." /><label>Nome<input name="nome" required placeholder="nome do usuário" /></label><label>Papel<select name="papel" defaultValue="professor"><option value="professor">Professor</option><option value="aluno">Aluno</option></select></label><label>E-mail<input name="email" required type="email" inputMode="email" autoComplete="email" placeholder="professor@academia.com" /></label><label>WhatsApp / telefone<input name="telefone" type="tel" inputMode="tel" autoComplete="tel" placeholder="(22) 99999-9999" /></label><label>Senha<input name="secret" required type="password" minLength={8} autoComplete="new-password" placeholder="mínimo 8 caracteres" /></label><button disabled={state === "loading"}>Criar usuário</button></form><section className="panel"><PanelTitle title="Usuários da unidade" action="Atualizar" onClick={onRefresh} /><List empty={statusText(error, "Nenhum usuário carregado.")} items={users} pick={(user) => [user.nome, user.papel, user.email || user.login_identifier || user.status]} /></section><form className="panel operational-form" onSubmit={onInvite}><FormHeader label="Convite" title="Gerar convite" text="O link leva o usuário para definir a própria credencial." /><label>Nome<input name="nome" required placeholder="nome do convidado" /></label><label>Papel<select name="papel" defaultValue="aluno"><option value="aluno">Aluno</option><option value="professor">Professor</option></select></label><label>E-mail sugerido<input name="login_identifier" type="email" inputMode="email" placeholder="aluno@email.com" /></label><button>Gerar convite</button></form><section className="panel"><h2>Convites recentes</h2><List empty="Nenhum convite recente." items={invites} pick={(invite) => [invite.nome_convidado || invite.nome, invite.papel, invite.status]} /><ActionSummary data={detail} /></section></div>; }
function StudentsPanel({ role, team, data, detail, state, error, onSubmit, onRefresh }: { role: string; team: Json; data: Json; detail: Json | null; state: LoadState; error: string; onSubmit: (event: FormEvent<HTMLFormElement>) => void; onRefresh: () => void }) { const studentItems = data.students || []; const users = team.users || []; const professors = users.filter((user: Json) => user.papel === "professor" || user.role === "professor"); const alunoUsers = users.filter((user: Json) => user.papel === "aluno" || user.role === "aluno"); if (!isStaffRole(role)) return <PermissionPanel title="Alunos" text="Aluno acessa treino e evolução. Cadastro operacional fica com gestor ou professor." />; return <div className="split-grid"><form className="panel operational-form" onSubmit={onSubmit}><FormHeader label="Alunos" title="Cadastrar aluno" text="Vincule o usuário aluno e o professor responsável antes de avançar para treinos." /><label>Nome público<input name="nome_publico" required placeholder="nome do aluno" /></label>{alunoUsers.length ? <label>Usuário aluno<select name="user_id" required defaultValue={alunoUsers[0]?.id}>{alunoUsers.map((user: Json) => <option key={user.id} value={user.id}>{user.nome}</option>)}</select></label> : <p className="muted-note">Crie primeiro um usuário com papel Aluno na área Equipe.</p>}{professors.length ? <label>Professor responsável<select name="professor_id" defaultValue={professors[0]?.id}>{professors.map((professor: Json) => <option key={professor.id} value={professor.id}>{professor.nome}</option>)}</select></label> : <p className="muted-note">Crie primeiro um professor na área Equipe.</p>}<label>Código interno<input name="codigo_publico" placeholder="opcional" /></label><label>Nível<select name="nivel" defaultValue="iniciante"><option value="iniciante">Iniciante</option><option value="intermediario">Intermediário</option><option value="avancado">Avançado</option></select></label><label>Objetivo<input name="objetivo" defaultValue="força e evolução" /></label><label>Modalidade<input name="modalidade_preferida" defaultValue="academia" /></label><label>Frequência semanal<input name="frequencia_semana" type="number" min="1" max="7" defaultValue="3" /></label><button disabled={state === "loading" || !alunoUsers.length || !professors.length}>Cadastrar e prescrever treino</button></form><section className="panel"><PanelTitle title="Alunos ativos" action="Atualizar" onClick={onRefresh} /><List empty={statusText(error, "Nenhum aluno carregado.")} items={studentItems} pick={(student) => [student.nome_publico, student.professor_nome || student.nivel, `${student.objetivo || "objetivo"} · ${student.frequencia_semana || 0}x/semana`]} /><ActionSummary data={detail} /></section></div>; }
function TrainingPanel({ role, students, data, detail, state, error, selectedStudentId, onSubmit, onReview, onRefresh }: { role: string; students: Json[]; data: Json; detail: Json | null; state: LoadState; error: string; selectedStudentId: string; onSubmit: (event: FormEvent<HTMLFormElement>) => void; onReview: (id: string, status: "aprovado" | "ajustes_solicitados") => void; onRefresh: () => void }) { const canPrescribe = role === "gestor" || role === "professor"; const prescriptions = data.prescriptions || data.workouts || []; return <div className="split-grid">{canPrescribe ? <form className="panel operational-form" onSubmit={onSubmit}><FormHeader label="Treinos" title="Nova prescrição" text="Escolha um aluno real da unidade. Nenhum ID manual é necessário." /><label>Aluno<select name="student_id" required defaultValue={selectedStudentId}>{students.length ? students.map((student) => <option key={student.id} value={student.id}>{student.nome_publico}</option>) : <option value="">Cadastre um aluno antes</option>}</select></label><label>Nome do treino<input name="nome_treino" required defaultValue="Treino base semanal" /></label><label>Objetivo<input name="objetivo" defaultValue="força e condicionamento" /></label><label>Modalidade<input name="modalidade" defaultValue="academia" /></label><label>Foco<input name="foco" defaultValue="corpo inteiro" /></label><label>Dias por semana<input name="dias_semana" type="number" min="1" max="7" defaultValue="3" /></label><label>Exercícios<textarea name="exercicios" defaultValue={"Agachamento frontal\nPuxada alta\nSupino com halteres\nRemada sentada"} /></label><label>Orientações<textarea name="orientacoes" defaultValue="Executar com controle, registrar esforço e avisar desconforto." /></label><button disabled={state === "loading" || !students.length}>Criar prescrição</button></form> : <PermissionPanel title="Treinos" text="Aluno visualiza treinos liberados. Prescrição e revisão ficam com gestor ou professor." />}<section className="panel"><PanelTitle title={role === "aluno" ? "Meus treinos" : "Treinos da unidade"} action="Atualizar" onClick={onRefresh} /><div className="item-list">{prescriptions.length ? prescriptions.map((item: Json) => <article className="item" key={item.id}><strong>{safe(item.nome_treino || item.workout_name || item.id)}</strong><span>{safe(item.student_name || item.aluno_nome || "meu treino")} · {safe(item.status)}</span><ExerciseMediaGrid limit={2} compact />{canPrescribe ? <div className="row-actions"><button type="button" onClick={() => onReview(String(item.id), "aprovado")}>Aprovar</button><button type="button" className="secondary" onClick={() => onReview(String(item.id), "ajustes_solicitados")}>Pedir ajuste</button></div> : null}</article>) : <article className="item"><strong>Nenhum treino carregado</strong><span>{statusText(error, canPrescribe ? "Cadastre aluno e crie uma prescrição." : "Seu treino aparece aqui após liberação.")}</span></article>}</div><ActionSummary data={detail} /></section></div>; }
function ExecutionPanel({ role, workouts, executions, detail, state, error, firstPrescriptionId, firstExecutionId, onStart, onMarkDone, onFinish, onRefresh, onAskAgent, agentAnswer }: { role: string; workouts: Json; executions: Json; detail: Json | null; state: LoadState; error: string; firstPrescriptionId: string; firstExecutionId: string; onStart: (workoutId: string) => void; onMarkDone: (executionId: string, index: number) => void; onFinish: (event: FormEvent<HTMLFormElement>) => void; onRefresh: () => void; onAskAgent: (prompt: string) => void; agentAnswer: Json | null }) { const approved = workouts.prescriptions || workouts.workouts || []; const items = executions.executions || []; const inProgress = items.filter((item: Json) => item.status === "em_execucao"); const isAluno = role === "aluno"; return <div className="student-workout-layout"><main><section className="panel workout-day-card"><div><span className="label">Treino do dia</span><h2>{approved[0]?.nome_treino || approved[0]?.workout_name || "Nenhum treino liberado"}</h2><p>{approved[0] ? `${safe(approved[0].objetivo || "Treino liberado")} · ${safe(approved[0].status)}` : "Aguardando uma prescrição real aprovada para esta conta."}</p></div><div className="quote">Disciplina é o que te faz continuar.</div></section><section className="metric-grid"><Metric label="Treinos liberados" value={approved.length} /><Metric label="Em execução" value={inProgress.length} /><Metric label="Concluídos" value={executions?.concluidos || 0} /><Metric label="Esforço médio" value={executions?.average_effort ?? "—"} /></section><section className="panel"><PanelTitle title="Exercícios do seu treino" action="Atualizar" onClick={onRefresh} /><ExerciseMediaGrid limit={4} onStart={() => firstPrescriptionId && onStart(firstPrescriptionId)} onMark={() => firstExecutionId && onMarkDone(firstExecutionId, 0)} /></section><section className="panel actions-panel"><h2>Ações permitidas</h2><div className="row-actions">{isAluno ? <><button type="button" onClick={() => onStart(firstPrescriptionId)} disabled={!firstPrescriptionId}>Iniciar treino liberado</button><button type="button" className="secondary" onClick={() => onMarkDone(firstExecutionId, 0)} disabled={!firstExecutionId}>Marcar próximo exercício</button></> : <span className="muted-note">Modo acompanhamento: gestor e professor visualizam. A execução é feita pelo aluno.</span>}<button type="button" className="secondary" onClick={onRefresh}>Recarregar painel</button></div><ActionSummary data={detail} /></section>{isAluno ? <form className="panel operational-form" onSubmit={onFinish}><FormHeader label="Aluno" title="Concluir execução" text="Selecione a sessão aberta. O sistema mantém você logado e registra o resultado." /><label>Execução em andamento<select name="execution_id" required defaultValue={firstExecutionId}>{inProgress.length ? inProgress.map((item: Json) => <option key={item.id} value={item.id}>{safe(item.nome_treino || item.workout_id)} · {safe(item.progresso_percentual)}%</option>) : <option value="">Inicie um treino antes</option>}</select></label><label>Esforço percebido<input name="percepcao_esforco" type="number" min="1" max="10" defaultValue="7" /></label><label>Duração em minutos<input name="duracao_minutos" type="number" min="1" max="480" defaultValue="45" /></label><label>Observações<textarea name="observacoes" defaultValue="Treino concluído com boa técnica." /></label><button disabled={state === "loading" || !firstExecutionId}>Concluir treino</button></form> : null}</main><aside><ProgressRing done={executions?.concluidos || 0} total={items.length || approved.length || 0} /><AgentPanel role={role} answer={agentAnswer} onAsk={onAskAgent} /><SecurityPanel session={null} compact /></aside></div>; }
function EvolutionPanel({ data, detail, state, error, isStaff, onStudent, onRefresh }: { data: Json; detail: Json | null; state: LoadState; error: string; isStaff: boolean; onStudent: (studentId: string) => void; onRefresh: () => void }) { const summary = data.summary || data.student || {}; const students = data.students || []; const weekly = data.weekly || []; const history = data.history || []; return <div className="dashboard-grid"><section className="panel wide"><PanelTitle title="Resumo de evolução" action="Atualizar" onClick={onRefresh} /><div className="metric-grid"><Metric label="Alunos" value={summary.students || (data.student ? 1 : 0)} /><Metric label="Execuções" value={summary.executions || summary.total_executions} /><Metric label="Concluídos" value={summary.completed || summary.completed_executions} /><Metric label="Esforço médio" value={summary.average_effort} /></div><Chart weekly={weekly} history={history} /></section>{isStaff ? <section className="panel"><h2>Progresso dos alunos</h2><div className="item-list">{students.length ? students.map((student: Json) => <button type="button" className="student-row" key={student.student_id} onClick={() => onStudent(String(student.student_id))}><strong>{safe(student.student_name)}</strong><span>{safe(student.completed_executions)} concluídos · esforço {safe(student.average_effort)} · {safe(student.progress_percent)}%</span></button>) : <article className="item"><strong>Nenhum progresso carregado</strong><span>{statusText(error, "Execute treinos para gerar histórico.")}</span></article>}</div></section> : <section className="panel"><h2>Minha evolução</h2>{data.student ? <MetricTable data={data} /> : <article className="item"><strong>Sem histórico</strong><span>{statusText(error, state === "loading" ? "Carregando..." : "Seu progresso aparece após concluir treinos.")}</span></article>}</section>}{detail ? <section className="panel wide"><h2>Detalhe do aluno</h2><MetricTable data={detail} /></section> : null}</div>; }
function AgentsPanel({ role, data, answer, onAsk }: { role: string; data: Json; answer: Json | null; onAsk: (prompt: string) => void }) { return <div className="dashboard-grid"><AgentPanel role={role} answer={answer} onAsk={onAsk} wide /><section className="panel"><h2>Criação com IA para profissionais</h2><div className="item-list">{agentPrompts.map((prompt) => <button type="button" className="student-row" key={prompt} onClick={() => onAsk(prompt)}><strong>{prompt}</strong><span>Baseado no aluno, treino, execução e evolução disponíveis.</span></button>)}</div></section><section className="panel wide"><h2>Contexto usado pelo assistente</h2><div className="metric-grid"><Metric label="Alunos" value={data.students?.total || data.students?.students?.length || 0} /><Metric label="Treinos" value={data.prescriptions?.total || 0} /><Metric label="Execuções" value={data.executions?.total || 0} /><Metric label="Evolução" value={data.evolution?.students?.length || data.evolution?.student?.total_executions || 0} /></div><p className="muted-note">O agente responde com base no papel logado e registra evento por unidade.</p></section></div>; }
function AgentPanel({ role, answer, onAsk, wide = false }: { role: string; answer: Json | null; onAsk: (prompt: string) => void; wide?: boolean }) { const allowed = role === "gestor" || role === "professor" || role === "aluno"; return <section className={`panel agent-panel ${wide ? "wide" : ""}`}><div className="agent-head"><span>✦</span><div><h2>{role === "aluno" ? "Assistente do aluno" : "IA para profissionais"}</h2><p>{role === "aluno" ? "Tire dúvidas sobre execução e segurança do treino." : "Crie, ajuste e revise treinos com dados da operação."}</p></div><b>Beta</b></div><div className="agent-actions">{agentPrompts.map((prompt) => <button type="button" className="secondary" key={prompt} disabled={!allowed} onClick={() => onAsk(prompt)}>{prompt}</button>)}</div><form className="agent-input" onSubmit={(event) => { event.preventDefault(); const input = event.currentTarget.elements.namedItem("prompt") as HTMLInputElement; const prompt = input.value.trim(); if (prompt) onAsk(prompt); input.value = ""; }}><input name="prompt" placeholder="Digite sua pergunta..." /><button type="submit" disabled={!allowed}>Enviar</button></form>{answer ? <article className="agent-answer"><strong>{safe(answer.title || "Resposta do agente")}</strong><p>{safe(answer.answer || answer.mensagem || answer.recommendation || "Ação registrada.")}</p></article> : <article className="agent-answer"><strong>Olá, posso ajudar?</strong><p>Peça um treino, ajuste de carga, explicação de exercício ou análise de evolução.</p></article>}</section>; }
function LibraryPanel({ workouts, onAskAgent }: { workouts: Json; onAskAgent: (prompt: string) => void }) {
  const [query, setQuery] = useState("");
  const [area, setArea] = useState("todos");
  const areas = ["todos", "pernas", "costas", "peito", "abdômen"];
  const filtered = exerciseMedia.filter((item) => {
    const hay = `${item.name} ${item.muscles} ${item.cue}`.toLowerCase();
    const q = query.trim().toLowerCase();
    const areaOk = area === "todos" || hay.includes(area) || (area === "peito" && hay.includes("peitoral")) || (area === "abdômen" && hay.includes("core"));
    return areaOk && (!q || hay.includes(q));
  });
  return <div className="dashboard-grid library-workspace">
    <section className="panel wide"><PanelTitle title="Biblioteca de exercícios com GIF" action="Criar treino com IA" onClick={() => onAskAgent("Criar treino usando exercícios com GIF da biblioteca")} /><div className="library-toolbar"><input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Buscar exercício, músculo ou cuidado técnico..." aria-label="Buscar exercício" /><div>{areas.map((item) => <button key={item} type="button" className={area === item ? "filter-pill active" : "filter-pill"} onClick={() => setArea(item)}>{item}</button>)}</div></div><ExerciseMediaGrid limit={12} items={filtered} /></section>
    <section className="panel"><h2>Como usar no treino</h2><div className="item-list"><article className="item"><strong>1. Escolha por músculo</strong><span>Filtre pernas, costas, peito ou abdômen.</span></article><article className="item"><strong>2. Prescreva com contexto</strong><span>Use o exercício na rota Treinos ou peça apoio ao agente.</span></article><article className="item"><strong>3. Aluno executa com GIF</strong><span>O aluno vê demonstração, séries, descanso e cuidado técnico.</span></article></div></section>
    <section className="panel"><h2>Treinos com mídia</h2><List empty="Crie uma prescrição para vincular mídia ao aluno." items={(workouts.prescriptions || []).slice(0, 5)} pick={(item) => [item.nome_treino || item.id, item.status, item.student_name]} /></section>
  </div>;
}

function ExerciseMediaGrid({ limit = 4, compact = false, onStart, onMark, items }: { limit?: number; compact?: boolean; onStart?: () => void; onMark?: () => void; items?: typeof exerciseMedia }) { const source = (items && items.length ? items : exerciseMedia).slice(0, limit); return <div className={`exercise-media-grid ${compact ? "is-compact" : ""}`}>{source.map((item, index) => <article className="exercise-media-card" key={item.slug}><div className="media-frame"><img src={`/media/exercises/${item.slug}.gif`} alt={`Demonstração de ${item.name}`} loading="lazy" /><span>{index + 1}</span></div><div><strong>{item.name}</strong><p>{item.muscles}</p><small>{item.sets} · Descanso: {item.rest}</small><em>{item.cue}</em></div><div className="media-actions"><button type="button" onClick={onStart}>Iniciar</button><button type="button" className="secondary" onClick={onMark}>Marcar feito</button></div></article>)}</div>; }

function SecurityPanel({ session, compact = false }: { session: Json | null; compact?: boolean }) { return <section className={`panel security-panel ${compact ? "compact" : ""}`}><h2>Seus dados, sempre protegidos</h2><p>LGPD, sessão assinada, cookies seguros, rate limit, auditoria por unidade e acesso por papel.</p><div className="security-list"><span>LGPD em conformidade</span><span>Dados protegidos</span><span>Permissões por papel</span><span>Auditoria ativa</span></div>{session ? <small>{safe(session.actor_role)} · {safe(session.tenant_slug)}</small> : null}</section>; }
function AuditPanel({ session, executions }: { session: Json | null; executions: Json }) { return <div className="dashboard-grid"><section className="panel wide"><h2>Auditoria da operação</h2><div className="metric-grid"><Metric label="Sessão" value={session ? "Ativa" : "—"} /><Metric label="Execuções" value={executions?.total || 0} /><Metric label="Eventos" value={executions?.events?.length || 0} /><Metric label="Escopo" value="Unidade" /></div></section><section className="panel"><h2>Últimos eventos</h2><List empty="Sem eventos carregados." items={executions?.events || []} pick={(event) => [event.evento || event.acao || "evento", event.status || "ok", event.criado_em || "recente"]} /></section></div>; }
function SettingsPanel({ session }: { session: Json | null }) { return <div className="dashboard-grid"><section className="panel wide"><h2>Configurações da unidade</h2><div className="settings-grid"><article><strong>Marca</strong><span>FitCore Pro</span></article><article><strong>Perfil</strong><span>{safe(session?.actor_role || "visitante")}</span></article><article><strong>Segurança</strong><span>Ativa</span></article><article><strong>Módulos</strong><span>Gestão, treino, IA e evolução</span></article></div></section></div>; }
function AgendaPanel({ students, executions }: { students: Json; executions: Json }) { return <div className="dashboard-grid"><section className="panel wide"><h2>Agenda operacional</h2><div className="timeline-list"><article><strong>Hoje</strong><span>Acompanhar execuções em andamento</span></article><article><strong>Esta semana</strong><span>Revisar alunos sem frequência registrada</span></article><article><strong>Próximo ciclo</strong><span>Atualizar prescrições e evolução</span></article></div></section><section className="panel"><h2>Resumo</h2><Metric label="Alunos" value={students?.total || students?.students?.length || 0} /><Metric label="Execuções" value={executions?.total || 0} /></section></div>; }
function ReportsPanel({ students, prescriptions, executions, evolution }: { students: Json; prescriptions: Json; executions: Json; evolution: Json }) { return <div className="dashboard-grid"><section className="panel wide"><h2>Relatórios executivos</h2><div className="metric-grid"><Metric label="Alunos" value={students?.total || students?.students?.length || 0} /><Metric label="Treinos" value={prescriptions?.total || 0} /><Metric label="Execuções" value={executions?.total || 0} /><Metric label="Esforço médio" value={evolution?.summary?.average_effort || 0} /></div><Chart weekly={evolution?.weekly || []} history={evolution?.history || []} /></section></div>; }
function FinancePanel({ students }: { students: Json }) { return <div className="dashboard-grid"><section className="panel wide"><h2>Financeiro</h2><div className="metric-grid"><Metric label="Alunos ativos" value={students?.total || students?.students?.length || 0} /><Metric label="Plano" value="Business" /><Metric label="Retenção" value="92%" /><Metric label="Pendências" value="0" /></div><p className="muted-note">Base preparada para cobrança, planos e inadimplência por unidade.</p></section></div>; }
function ProgressRing({ done, total }: { done: number; total: number }) { const pct = total > 0 ? Math.round(Math.min(100, Math.max(0, (done / total) * 100))) : 0; return <section className="panel progress-panel"><h2>Seu progresso hoje</h2><div className="progress-ring" style={{ ["--progress" as any]: `${pct}%` }}><strong>{pct}%</strong><span>{done} de {total} exercícios</span></div><p>{pct ? "Continue até concluir a sessão." : "Inicie o primeiro exercício para começar."}</p></section>; }
function PermissionPanel({ title, text }: { title: string; text: string }) { return <article className="panel permission-panel"><span className="label">Acesso por papel</span><h2>{title}</h2><p>{text}</p><Link className="button secondary" href="/">Voltar para visão geral</Link></article>; }
function FormHeader({ label, title, text }: { label: string; title: string; text: string }) { return <div className="form-head"><span className="label">{label}</span><h2>{title}</h2><p>{text}</p></div>; }
function PanelTitle({ title, action, onClick }: { title: string; action?: string; onClick?: () => void }) { return <div className="panel-title"><h2>{title}</h2>{action ? <button type="button" className="secondary" onClick={onClick}>{action}</button> : null}</div>; }
function FlowHeader({ current, next, href }: { current: string; next: string; href: string }) { return <div className="flow-header"><span>Configuração guiada</span><strong>{current}</strong><Link className="primary-pill" href={href}>Próximo: {next}</Link></div>; }
function FlowCard({ title, text }: { title: string; text: string }) { return <article className="flow-card"><strong>{title}</strong><span>{text}</span></article>; }
function Process({ steps }: { steps: string[] }) { return <div className="process-list">{steps.map((step, index) => <div key={step}><span>{String(index + 1).padStart(2, "0")}</span><strong>{step}</strong></div>)}</div>; }
function List({ items, pick, empty }: { items: Json[]; pick: (item: Json) => any[]; empty: string }) { return <div className="item-list">{items.length ? items.map((item, index) => { const row = pick(item); return <article className="item" key={safe(item.id || `${row[0]}-${index}`)}><strong>{safe(row[0])}</strong><span>{safe(row[1])} · {safe(row[2])}</span></article>; }) : <article className="item"><strong>Sem dados</strong><span>{empty}</span></article>}</div>; }
function ActionSummary({ data }: { data: Json | null }) { if (!data) return null; const entity = data.user || data.student || data.prescription || data.execution || data.invite || data.session || {}; const title = entity.nome || entity.nome_publico || entity.nome_treino || entity.nome_convidado || entity.actor_name || data.mvp || "Ação concluída"; const subtitle = entity.papel || entity.status || entity.tenant_slug || data.tenant_slug || (data.ok ? "Concluído" : "Atualizado"); const url = data.invite?.public_url || data.invite?.full_invite_url || data.public_url || ""; return <article className="action-summary"><span>Última ação</span><strong>{safe(title)}</strong><small>{safe(subtitle)}</small>{url ? <a href={url}>Abrir convite</a> : null}</article>; }
function Metric({ label, value, hint }: { label: string; value: any; hint?: string }) { return <div className="metric"><span>{label}</span><strong>{typeof value === "string" ? value : numberText(value)}</strong>{hint ? <small>{hint}</small> : null}</div>; }
function Chart({ weekly, history }: { weekly: Json[]; history: Json[] }) { const source: Json[] = weekly.length ? weekly : history.slice(0, 8).map((item, index) => ({ week: `#${index + 1}`, completed: item.status === "concluido" ? 1 : 0 })); const max = Math.max(1, ...source.map((item) => Number(item.completed || item.executions || 0))); return <div className="chart">{source.length ? source.map((item) => { const value = Number(item.completed || item.executions || 0); return <div className="bar" key={safe(item.week || item.id)} style={{ height: `${Math.max(10, (value / max) * 100)}%` }}><span>{value}</span><small>{safe(item.week || "exec")}</small></div>; }) : <div className="empty-chart">Histórico aparece após execuções concluídas.</div>}</div>; }
function MetricTable({ data }: { data: Json }) { const student = data.student || {}; const history = data.history || []; const byWorkout = data.by_workout || []; return <><div className="metric-grid"><Metric label="Execuções" value={student.total_executions} /><Metric label="Frequência" value={student.weekly_frequency} /><Metric label="Esforço" value={student.average_effort} /><Metric label="Progresso" value={student.progress_percent} /></div><div className="table"><div><strong>Treino</strong><strong>Status</strong><strong>Duração</strong></div>{history.length ? history.map((item: Json) => <div key={item.id}><span>{safe(item.nome_treino || item.workout_id)}</span><span>{safe(item.status)}</span><span>{safe(item.duracao_minutos)} min</span></div>) : byWorkout.length ? byWorkout.map((item: Json) => <div key={item.workout_id || item.nome_treino}><span>{safe(item.nome_treino || item.workout_id)}</span><span>{safe(item.completed_executions)} concluídos</span><span>{safe(item.average_duration)} min</span></div>) : <div><span>Sem histórico</span><span>—</span><span>—</span></div>}</div></>; }
